diff --git a/src/feature-app/LineItem.tsx b/src/feature-app/LineItem.tsx
new file mode 100644
index 0000000..c312f12
--- /dev/null
+++ b/src/feature-app/LineItem.tsx
@@ -0,0 +1,67 @@
+/**
+ * @file just for call Payment calculator Feature App for DEV development
+ */
+import {useFeatureAppEnv} from '@smart/feature-app';
+import {TextButton} from '@smart/web-components';
+import * as React from 'react';
+
+type LineItemProps = {
+  pn18: string;
+};
+function LineItem(props: LineItemProps) {
+  const code = props.pn18;
+  const {
+    featureAppId,
+    featureServices: {'payment-config-service': paymentConfigService},
+  } = useFeatureAppEnv();
+
+  const [paymentConfig, setPaymentConfig] = React.useState(
+    paymentConfigService.getConfig(),
+  );
+
+  React.useEffect(
+    () =>
+      paymentConfigService.subscribe(({consumerId, purchaseItem}) => {
+        if (
+          consumerId === featureAppId &&
+          purchaseItem.type === `pn18` &&
+          purchaseItem.pn18 === code
+        ) {
+          setPaymentConfig(paymentConfigService.getConfig());
+        }
+      }),
+    [featureAppId, code, paymentConfigService],
+  );
+
+  React.useEffect(
+    () =>
+      paymentConfigService.subscribe(
+        async () => {
+          await new Promise((r) => setTimeout(r, 1000));
+        },
+        {matchers: [`submit`]},
+      ),
+    [paymentConfigService, code, paymentConfigService],
+  );
+
+  const handleClick = React.useCallback(
+    () =>
+      paymentConfigService.openCalculator({
+        purchaseItem: {type: `pn18`, pn18: code},
+        initialConfig: paymentConfig,
+      }),
+    [code, paymentConfigService, paymentConfig],
+  );
+
+  return (
+    <>
+      <div>
+        <TextButton variant="hyperlink" onClick={handleClick}>
+          Customize Payment for PN18 code is {code}
+        </TextButton>
+        <pre>{JSON.stringify(paymentConfig, null, 2)}</pre>
+      </div>
+    </>
+  );
+}
+export default LineItem;

