+  const privateUrl = `/__app-private__/${featureAppName}/${target}`;
+
+  const api = new Api(stack, `BffApi`, {
+    customDomain: {
+      hostedZone,
+      domainName: [`stage`, `dev`, `prod`].includes(stack.stage)
+        ? `bff.${hostedZone}`
+        : `bff.${stack.stage}.${hostedZone}`,
+    },
+    routes: {
+      [`GET ${baseUrl}/bff/app-model`]: {
+        function: {
+          handler: `src/bff/app-model/index.handler`,
+          functionName: `BffAppModelFunction-${featureAppName}-${target}`,
+          memorySize: 1769,
+        },
+      },
+      [`GET ${baseUrl}/bff/price-details`]: {
+        function: {
+          handler: `src/bff/price-details/index.handler`,
+          functionName: `BffPriceDetailsFunction-${featureAppName}-${target}`,
+          memorySize: 1769,
+        },
+      },
+      [`GET ${baseUrl}/bff/leasing-information`]: {
+        function: {
+          handler: `src/bff/leasing-information/index.handler`,
+          functionName: `BffLeasingInformationFunction-${featureAppName}-${target}`,
+          memorySize: 1769,
+        },
+      },
+      [`GET ${privateUrl}/bff/cart-price-details`]: {
+        function: {
