+    stage,
+    featureAppName,
+    hostedZone,
+  });
+
+  const webConfig = getWebAppConfig({
+    mode,
+    stage,
+    target,
+    baseUrl,
+    privateBaseUrl,
+    featureAppName,
+    hostedZone,
+  });
+
+  return [featureAppConfig, webConfig];
+};

